'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{pathToFileURL}=require('node:url');
async function qualifyProtectedRecoveryFullApp({identity,migration,auth,identityRepository,targets,owner,sibling,intent,runtimeRoot}){
 const express=require('express'),app=express();app.use(express.json());let backend,vite,browser,production,authRouter;const pages=[];
 try{
  production=await require('../../server/services/mcp/protectedRecoveryProduction').createProtectedRecoveryProduction({env:{MCP_PROTECTED_RECOVERY_ENABLED:'true',IDENTITY_DATABASE_URL:process.env.PG_GRAPH_TEST_RUNTIME_URL,MCP_WORKSHOP_DATABASE_URL:process.env.PG_MCP_RUNTIME_URL},identityAdapter:{pool:identity,validateSession:t=>auth.validateSession(t)},targets});
  const middleware=require('../../server/middleware/postgresAdminAuth').createPostgresAdminAuth(auth);
  const pass=(_q,_r,next)=>next();authRouter=require('../../server/routes/postgresAuth').createPostgresAuthRouter({adapter:auth,limiters:{loginRateLimiter:pass,registerRateLimiter:pass,passwordResetRateLimiter:pass}});app.use('/api/auth',authRouter);
  assert.equal(Number((await identity.query("SELECT count(*) FROM graph_runtime.runs WHERE owner_key::jsonb->>0='SecureShopBoundConversation'")).rows[0].count),0);
  const read=require('../../server/database/postgres/agentRunReadRepository').createPostgresAgentRunReadRepository(identity,{secureShopOwnership:{resolve:async()=>null,listOwnedConversationIds:async()=>[],resolveMany:async()=>new Map()}});
  const router=require('../../server/routes/agentRuns').createAgentRunsRouter;
  app.use('/api/agent-runs',router({repository:read,authenticateToken:middleware.authenticateToken,receiptAdapters:{},listJudgments:async()=>[],protectedRecoveryAvailable:()=>true}));
  app.use('/api/admin/agent-runs',router({repository:read,authenticateToken:middleware.authenticateToken,requirePermission:middleware.requirePermission,admin:true,receiptAdapters:{}}));
  app.post('/api/workshop/mcp/protected-operations/reconcile',middleware.authenticateToken,require('../../server/services/mcp/protectedRecoveryRoute').createProtectedRecoveryHandler({getService:()=>production}));
  backend=await new Promise(r=>{const s=app.listen(0,'127.0.0.1',()=>r(s));});process.env.PORT=String(backend.address().port);
  const admin=await identityRepository.createUser({username:'recovery-admin-'+Date.now(),email:'admin-'+Date.now()+'@example.invalid',passwordHash:await require('bcryptjs').hash('fixture',4)});await migration.query("UPDATE identity.users SET role='super_admin',admin_level=2,email_verified=1 WHERE id=$1",[admin.id]);await identityRepository.grantPermission({userId:admin.id,permission:'view_analytics',grantedBy:admin.id});const adminSession=await auth.createSession(await identityRepository.findCredentialById(admin.id),{});
  const alternate=await auth.createSession(await identityRepository.findCredentialById(owner.id),{});
  const clientRoot=path.resolve('client');const {createServer}=await import(pathToFileURL(path.join(clientRoot,'node_modules/vite/dist/node/index.js')));
  vite=await createServer({root:clientRoot,configFile:path.join(clientRoot,'vite.config.mjs'),configLoader:'native',cacheDir:path.join(runtimeRoot,'vite-recovery-cache'),server:{host:'127.0.0.1',port:0,strictPort:false,fs:{allow:[clientRoot,fs.realpathSync(path.join(clientRoot,'node_modules'))]}}});await vite.listen();const origin='http://127.0.0.1:'+vite.httpServer.address().port;
  browser=await require('puppeteer').launch({headless:true,userDataDir:path.join(runtimeRoot,'protected-browser')});const pid=browser.process().pid;fs.writeFileSync(path.join(runtimeRoot,'protected-browser-owner.json'),JSON.stringify({pid}));
  const make=async token=>{const context=await browser.createBrowserContext(),page=await context.newPage();pages.push(page);await page.setViewport({width:1440,height:1100});await page.evaluateOnNewDocument(t=>localStorage.setItem('token',t),token);await page.setRequestInterception(true);page.on('request',r=>r.url().startsWith(origin+'/')||/^(data|blob|about):/.test(r.url())?r.continue():r.abort());return page;};
  const selectOriginal=async page=>{const target=`[data-run-id="${intent.run_id}"]`;await page.waitForSelector(target,{timeout:30000});await page.$eval(target,e=>e.click());};
  const token=owner.request.headers.authorization.slice(7),page=await make(token);await page.goto(origin+'/workshop/agent-runs');await selectOriginal(page);const selector=`[data-protected-operation-id="${intent.operation_id}"]`;await page.waitForSelector(selector,{timeout:45000});
  assert.match(await page.$eval(selector,e=>e.innerText),/Original effect: uncertain/);await page.$eval(selector,e=>Array.from(e.querySelectorAll('button')).find(b=>b.textContent.includes('Check receipt')).click());await page.waitForFunction(s=>document.querySelector(s)?.innerText.includes('Receipt: completed'),{timeout:15000},selector);
  assert.match(await page.$eval('body',e=>e.innerText),/failed/);assert.match(await page.$eval(selector,e=>e.innerText),/does not rerun the tool/);
  await page.screenshot({path:path.join(runtimeRoot,'protected-owner-recovered.png'),fullPage:true});
  const newer=await make(alternate.token);await newer.goto(origin+'/workshop/agent-runs');await selectOriginal(newer);await newer.waitForSelector(selector,{timeout:45000});assert.equal(await newer.$$eval(selector+' button',es=>es.length),0);
  const foreign=await make(sibling.request.headers.authorization.slice(7));await foreign.goto(origin+'/workshop/agent-runs');await foreign.waitForFunction(()=>document.body.innerText.includes('Your agent runs'),{timeout:45000});assert.equal(await foreign.$(selector),null);assert.equal(await foreign.evaluate(async run=>fetch('/api/agent-runs/'+run,{headers:{Authorization:'Bearer '+localStorage.getItem('token')}}).then(r=>r.status),intent.run_id),404);
  const observer=await make(adminSession.token);await observer.goto(origin+'/admin/agent-runs');await selectOriginal(observer);await observer.waitForSelector(selector,{timeout:45000});assert.equal(await observer.$$eval(selector+' button',es=>es.length),0);await observer.screenshot({path:path.join(runtimeRoot,'protected-admin-observer.png'),fullPage:true});
  for(const [actor,expected] of [[newer,404],[foreign,404],[observer,404]])assert.equal(await actor.evaluate(async id=>fetch('/api/workshop/mcp/protected-operations/reconcile',{method:'POST',headers:{Authorization:'Bearer '+localStorage.getItem('token'),'content-type':'application/json'},body:JSON.stringify({operationId:id})}).then(r=>r.status),intent.operation_id),expected);
  assert.equal((await identity.query('SELECT status FROM graph_runtime.effects WHERE run_id=$1',[intent.run_id])).rows[0].status,'uncertain');
  return {fullAppReact:true,scopedCanonicalBackend:true,realJwt:true,actualLostAckReceipt:true,ownerMetadataReadback:true,newSessionDenied:true,foreignDenied:true,adminObserverOnly:true,originalEffectUnchanged:true,actualModel:false,browserPid:pid};
 }catch(error){for(let i=0;i<pages.length;i++){fs.writeFileSync(path.join(runtimeRoot,`protected-failure-${i}.txt`),await pages[i].$eval('body',e=>e.innerText).catch(()=>''));await pages[i].screenshot({path:path.join(runtimeRoot,`protected-failure-${i}.png`),fullPage:true}).catch(()=>{});}throw error;}finally{if(browser)await browser.close();if(vite)await vite.close();if(backend)await new Promise(r=>{backend.closeAllConnections();backend.close(r);});await authRouter?.close?.();await production?.close();}
}
module.exports={qualifyProtectedRecoveryFullApp};
